import{z as d,x as p,o as i,c as C,q as n,j as o,D as r,d as e,s as l,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"编译器模糊测试 Csmith","description":"","frontmatter":{"title":"编译器模糊测试 Csmith","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compiler-fuzzing.md","filePath":"cs/compiler-fuzzing.md","lastUpdated":1791413859000}'),m={name:"cs/compiler-fuzzing.md"};function B(A,a,u,h,c,g){const s=p("Mermaid");return i(),C("div",null,[a[2]||(a[2]=n('<h1 id="编译器模糊测试-csmith" tabindex="-1">编译器模糊测试 Csmith <a class="header-anchor" href="#编译器模糊测试-csmith" aria-label="Permalink to &quot;编译器模糊测试 Csmith&quot;">​</a></h1><div class="epigraph"><p>随机生成仍属于定义行为的 C 程序，在多个编译器或优化级别间比较输出。差异则是 bug。这是测试，不是 CompCert 的证明。</p><footer>—— 据 Yang, Chen, Eide and Regehr, Finding and Understanding Bugs in C Compilers, 2011；对照 CompCert 整理</footer></div><p>上一课<a href="/cs/compcert-correctness">CompCert</a> 给出证明路线。缺口是对 <strong>GCC/LLVM</strong> 的找虫：Csmith 生成避免 UB 的程序，差分测试。自举下一课收束课程。不发明 arXiv；Yang et al. PLDI 2011 是锚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手写用例覆盖不到优化组合。随机程序太大，若含 UB，差分无意义（优化可合法不同）。Csmith：静态避免许多 UB（不越界、不未初始化用、谨慎有符号溢出）。缺口是<strong>生成器纪律 + 差分</strong>，不是 Coq 战术。</p><p>发现：未定义假设过强、错误的别名、错误的卷绕。</p><p><span class="marginnote">术语翻译：差分测试（differential testing）就是「同一道题让多位考生作答，答案不一致则至少有一人错了」——不需要标准答案。用在编译器上：同一程序、同样输入，不同编译器或不同优化级别给出不同输出，必有一个违反了语义。</span></p><h3 id="fuzz-不是证明" tabindex="-1">fuzz 不是证明 <a class="header-anchor" href="#fuzz-不是证明" aria-label="Permalink to &quot;fuzz 不是证明&quot;">​</a></h3><p>未找到 bug ≠ 正确。与 CompCert 互补：一个保子集，一个打工业编译器。</p><p><span class="marginnote">Yang et al. 2011 PLDI。Regehr 组后续 C-Reduce。本课不把 AFL 当 C 语义生成器；AFL 不保证无 UB。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成 → 多编译器运行 → 比 stdout/返回值。失败：缩减（C-Reduce）得小用例。也可对解释器/CompCert 当参考。</p><p><span class="marginnote">直觉类比：C-Reduce 像给 bug 瘦身——机械地反复尝试删代码，每删一块就确认 bug 仍然复现，删不动为止。几千行的随机程序最后缩成十几行，编译器开发者才看得懂、修得了。</span></p>',13)),(i(),o(E,null,{default:r(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22Csmith%20%E7%94%9F%E6%88%90%22%5D%20--%3E%20C1%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%20A%22%5D%0A%20%20GEN%20--%3E%20C2%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%20B%22%5D%0A%20%20C1%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%88%86%22%5D%0A%20%20C2%20--%3E%20DIFF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("与"),t("a",{href:"/cs/language-memory-model"},"内存模型"),e("：并发生成更难，Csmith 以单线程为主。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("超时、栈溢出要当测试工具问题。优化级别 "),t("code",null,"-O0"),e(" vs "),t("code",null,"-O2"),e(" 也是差分对。不要用含 UB 的还原用例去「证明编译器坏」。")],-1)),a[6]||(a[6]=t("p",null,"覆盖：随机仍有盲区（某条稀有 IR 形状）。",-1)),(i(),o(E,null,{default:r(()=>[l(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIFF%5B%22%E5%B7%AE%E5%88%86%E5%8F%91%E7%8E%B0%E8%BE%93%E5%87%BA%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%20--%3E%20CHK%7B%22%E7%94%A8%E4%BE%8B%E6%98%AF%E5%90%A6%E5%90%AB%E6%9C%AA%E5%AE%9A%E4%B9%89%E8%A1%8C%E4%B8%BA%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%90%AB%20UB%22%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%3A%20%E5%B7%AE%E5%BC%82%E5%8F%AF%E8%83%BD%E5%90%88%E6%B3%95%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%97%A0%20UB%22%7C%20RED%5B%22C-Reduce%20%E8%87%AA%E5%8A%A8%E7%BC%A9%E5%87%8F%22%5D%0A%20%20RED%20--%3E%20MIN%5B%22%E6%9C%80%E5%B0%8F%E5%A4%8D%E7%8E%B0%E7%94%A8%E4%BE%8B%22%5D%0A%20%20MIN%20--%3E%20REP%5B%22%E6%8A%A5%E5%91%8A%E7%BB%99%E7%BC%96%E8%AF%91%E5%99%A8%E5%BC%80%E5%8F%91%E8%80%85%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：假设随机程序里发生了有符号整数溢出。C 标准说这是 UB：一个编译器把值回绕成负数，另一个在 <code>-O2</code> 直接假设「不会溢出」而删掉判断——两个都合法，差分响起的不是 bug，而是标准允许的自由度。这正是 Csmith 要在生成时静态避开 UB 的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写自举。后课默认：工业编译器用生成+差分找虫。下一课自举：编译器用自己编译自己。</p><p>也不把 fuzz 当网络协议 fuzz 教程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Csmith：无 UB 随机 C + 差分测试找编译器 bug。</li><li>与形式化验证互补，不是替代。</li><li>缩减得到可报告用例。</li><li>出处：Yang, Chen, Eide and Regehr, 2011。</li></ul>',6))])}const b=d(m,[["render",B]]);export{D as __pageData,b as default};
